 *         Compatible with zkpassport/poseidon2 v0.6.x and Noir stdlib poseidon2.
 *
 * The 2-input sponge hash (used for Merkle tree node hashing) is the primary
 * export: hash2(a, b). Domain-IV encoding matches the JS FieldSponge:
 *   initial state = [a, b, 0, (inputLen << 64) + (outLen - 1)]
 *   For 2 inputs, 1 output: IV = (2 << 64) + 0 = 0x20000000000000000
 */
library Poseidon2BN254 {
    // BN254 scalar field prime r = 21888242871839275222246405745257275088548364400416034343698204186575808495617
    uint256 internal constant Q =
        0x30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001;

    // Domain IV for sponge hash of 2 inputs → 1 output
    // = (uint256(2) << 64) = 36893488147419103232
    uint256 internal constant DOM_IV_2 = uint256(2) << 64;

    // Domain IV for sponge hash of 4 inputs → 1 output
    // = (uint256(4) << 64)
    uint256 internal constant DOM_IV_4 = uint256(4) << 64;

    // ── Diagonal elements of M_I (mat_internal_diag_m_1) ────────────────────
    uint256 internal constant D0 = 0x10dc6e9c006ea38b04b1e03b4bd9490c0d03f98929ca1d7fb56821fd19d3b6e7;
    uint256 internal constant D1 = 0x0c28145b6a44df3e0149b3d0a30b3bb599df9756d4dd9b84a86b38cfb45a740b;
    uint256 internal constant D2 = 0x00544b8338791518b2c7645a50392798b21f75bb60e3596170067d00141cac15;
    uint256 internal constant D3 = 0x222c01175718386f2e2e82eb122789e352e105a3b8fa852613bc534433ee428b;

    // ─────────────────────────────────────────────────────────────────────────
    // Public interface
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Poseidon2 hash of two field elements (used for Merkle tree nodes).
     *         Matches poseidon2Hash([a, b]) in the zkpassport/poseidon2 library.
     */
    function hash2(uint256 a, uint256 b) internal pure returns (uint256) {
        uint256[4] memory s;
        s[0] = a;
        s[1] = b;
        s[2] = 0;
        s[3] = DOM_IV_2;
        _permute(s);
        return s[0];
    }

    /**
     * @notice Poseidon2 hash of four field elements (used for note commitments).
     *         Matches poseidon2Hash([a, b, c, d]) in the zkpassport/poseidon2 library.
     */
    function hash4(uint256 a, uint256 b, uint256 c, uint256 d) internal pure returns (uint256) {
        uint256[4] memory s;
        s[0] = a;
        s[1] = b;
        s[2] = c;
        s[3] = uint256(DOM_IV_4);
        // Absorb a and b in first call (rate=3, so first duplex: s[0..2] += [a,b,c])
        // Actually for 4 inputs the sponge does two permutations — we need the full sponge.
        // Delegate to the correct sponge implementation.
        return _sponge4(a, b, c, d);
