    // ── S-box: x → x^5 mod Q ─────────────────────────────────────────────────

    function _sboxP(uint256 x) private pure returns (uint256) {
        uint256 x2 = mulmod(x, x, Q);
        uint256 x4 = mulmod(x2, x2, Q);
        return mulmod(x4, x, Q);
    }

    // ── Linear layers ─────────────────────────────────────────────────────────

    /// matmulExternal for t=4 (M_E applied in-place).
    function _matMulExternal(uint256[4] memory s) private pure {
        unchecked {
            // Translated directly from the @zkpassport/poseidon2 matmulExternal (t==4 branch)
            uint256 t0 = addmod(s[0], s[1], Q);          // s[0]+s[1]
            uint256 t1 = addmod(s[2], s[3], Q);          // s[2]+s[3]
            uint256 t2 = addmod(addmod(s[1], s[1], Q), t1, Q); // 2s[1]+t1
            uint256 t3 = addmod(addmod(s[3], s[3], Q), t0, Q); // 2s[3]+t0
            uint256 t4 = addmod(addmod(addmod(t1, t1, Q), addmod(t1, t1, Q), Q), t3, Q); // 4t1+t3
            uint256 t5 = addmod(addmod(addmod(t0, t0, Q), addmod(t0, t0, Q), Q), t2, Q); // 4t0+t2
            uint256 t6 = addmod(t3, t5, Q);
            uint256 t7 = addmod(t2, t4, Q);
            s[0] = t6;
            s[1] = t5;
            s[2] = t7;
            s[3] = t4;
        }
    }

    /// matmulInternal for t=4 (M_I applied in-place using diagonal D).
    function _matMulInternal(uint256[4] memory s) private pure {
        uint256 sum = addmod(addmod(addmod(s[0], s[1], Q), s[2], Q), s[3], Q);
        s[0] = addmod(mulmod(D0, s[0], Q), sum, Q);
        s[1] = addmod(mulmod(D1, s[1], Q), sum, Q);
        s[2] = addmod(mulmod(D2, s[2], Q), sum, Q);
        s[3] = addmod(mulmod(D3, s[3], Q), sum, Q);
    }

    // ── Field addition ────────────────────────────────────────────────────────

    function _addQ(uint256 a, uint256 b) private pure returns (uint256 r) {
        unchecked {
            r = a + b;
            if (r >= Q) r -= Q;
        }
    }
}

